    "absolute_risk_difference": "-0.69%",
    "nnt": "144",
    "arithmetic": "Matched cohort: Risk(GLP-1) = 247 / 15,264 = 1.618%; Risk(Control) = 353 / 15,264 = 2.313%; ARD = 1.618% - 2.313% = -0.694% (-0.006944); ARR = 0.694%; NNT = 1 / 0.006944 = 144.0"
  },
  "classification": "real_association_explained_by_selection",
  "unresolvable_without_more_data": [
    "Data on post-exposure co-interventions and adjuvant therapies across both arms.",
    "Data on EHR completeness, missingness proportion, and patient loss to follow-up.",
    "Exact mammography screening frequency per patient during follow-up to settle direction of surveillance bias.",
    "Time-to-event data with competing risks of death (Fine-Gray / cause-specific hazards)."
  ]
}
